// InvoiceDesk: validate the approved follow-up from POST /webhook/invoicedesk-followup before
// any e-mail is sent. The API sends {followup_id, document_id, to, subject, body}; the recipient
// came from the vendor master, never from the invoice. Defense in depth: header-injection
// checks, an optional recipient-domain allow-list, and long digit runs masked to the last 4.
const EMAIL = /^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?)+$/;
const allowed = String($env.FOLLOWUP_ALLOWED_RECIPIENT_DOMAINS || '')
  .split(',').map((d) => d.trim().toLowerCase()).filter(Boolean);

function maskDigits(s) {
  return s.replace(/\d{6,}/g, (run) => '••••' + run.slice(-4));
}

return $input.all().map((item) => {
  const b = (item.json && item.json.body) || {};
  const errors = [];
  const str = (v) => (typeof v === 'string' ? v : '');
  const to = str(b.to).trim();
  const subject = str(b.subject).trim();
  const text = str(b.body).trim();
  const followupId = str(b.followup_id).trim();
  const documentId = str(b.document_id).trim();

  if (!followupId) errors.push('followup_id is missing');
  if (!EMAIL.test(to) || to.length > 320) errors.push('to is not a single e-mail address');
  if (allowed.length > 0 && !allowed.includes(to.split('@').pop().toLowerCase())) {
    errors.push('recipient domain is not on FOLLOWUP_ALLOWED_RECIPIENT_DOMAINS');
  }
  if (!subject || subject.length > 200 || /[\r\n]/.test(subject)) errors.push('subject is empty, too long or multi-line');
  if (!text || text.length > 5000) errors.push('body is empty or too long');

  return {
    json: {
      ok: errors.length === 0,
      errors,
      followup_id: followupId,
      document_id: documentId,
      to,
      subject: maskDigits(subject),
      text: maskDigits(text),
    },
  };
});
